/**
 * Errors that can cross the UniFFI boundary from the Kotlin adapters back
 * into the Rust engine. UniFFI requires every foreign-trait method to return
 * `Result<_, CompatibleError>`; this is the compatible error type.
 */
sealed class IrisFfiException: kotlin.Exception() {
    
    class NotSupported(
        ) : IrisFfiException() {
        override val message
            get() = ""
    }
    
    class PermissionDenied(
        ) : IrisFfiException() {
        override val message
            get() = ""
    }
    
    class AdapterOff(
        ) : IrisFfiException() {
        override val message
            get() = ""
    }
    
    class DeviceNotFound(
        ) : IrisFfiException() {
        override val message
            get() = ""
    }
    
    class GattFailure(
        
        val v1: kotlin.String
        ) : IrisFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Timeout(
        ) : IrisFfiException() {
        override val message
            get() = ""
    }
    
    class IoException(
        
        val v1: kotlin.String
        ) : IrisFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidArgument(
        
        val v1: kotlin.String
        ) : IrisFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Transport(
        
        val v1: kotlin.String
        ) : IrisFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<IrisFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): IrisFfiException = FfiConverterTypeIrisFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeIrisFfiError : FfiConverterRustBuffer<IrisFfiException> {
    override fun read(buf: ByteBuffer): IrisFfiException {
        

        return when(buf.getInt()) {
            1 -> IrisFfiException.NotSupported()
            2 -> IrisFfiException.PermissionDenied()
            3 -> IrisFfiException.AdapterOff()
            4 -> IrisFfiException.DeviceNotFound()
            5 -> IrisFfiException.GattFailure(
                FfiConverterString.read(buf),
                )
            6 -> IrisFfiException.Timeout()
            7 -> IrisFfiException.IoException(
                FfiConverterString.read(buf),
                )
            8 -> IrisFfiException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            9 -> IrisFfiException.Transport(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: IrisFfiException): ULong {
        return when(value) {
            is IrisFfiException.NotSupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is IrisFfiException.PermissionDenied -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is IrisFfiException.AdapterOff -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is IrisFfiException.DeviceNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is IrisFfiException.GattFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IrisFfiException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is IrisFfiException.IoException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IrisFfiException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IrisFfiException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: IrisFfiException, buf: ByteBuffer) {
        when(value) {
            is IrisFfiException.NotSupported -> {
                buf.putInt(1)
                Unit
            }
            is IrisFfiException.PermissionDenied -> {
                buf.putInt(2)
                Unit
            }
            is IrisFfiException.AdapterOff -> {
                buf.putInt(3)
                Unit
            }
            is IrisFfiException.DeviceNotFound -> {
                buf.putInt(4)
                Unit
            }
            is IrisFfiException.GattFailure -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IrisFfiException.Timeout -> {
                buf.putInt(6)
                Unit
            }
            is IrisFfiException.IoException -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IrisFfiException.InvalidArgument -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IrisFfiException.Transport -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




